import { Modal } from "antd";
import React, { useEffect, useState } from "react";
import { ToastContainer } from "react-toastify";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  CustomTimePicker,
} from "../../../components";
import useApi from "../../../hooks/useApi";
import transportApi from "../../../api/transport/transportApi";
import { useFormik } from "formik";
import * as Yup from "yup";
import dayjs from "dayjs";
import { Button } from "@heroui/react";
import countiesApi from "../../../api/countiesApi";

function IntercityFormModal({
  ismodalOpen,
  setisModalOpen,
  journey,
  modalTitle = "Add new intercity journey",
  updated,
  setUpdated,
}) {
  const getTransferPointsActionsApi = useApi(transportApi.transportAction);
  const getVehiclesActionsApi = useApi(transportApi.transportAction);
  const transportActionsApi = useApi(transportApi.transportAction);
  const [saccoDrivers, setsaccoDrivers] = useState([]);
  const [transferPoints, setTransferPoints] = useState([]);
  const getTransferPoints = async () => {
    await getTransferPointsActionsApi.request({
      action: "GetEntityTransferPoints",
    });
  };
  const getVehicles = async () => {
    await getVehiclesActionsApi.request({
      action: "GetEntityVehicles",
    });
  };
  const [towns, setTowns] = useState([]);
  const getTownsApi = useApi(countiesApi.countiesAction);
  const getTowns = async () => {
    await getTownsApi.request({
      action: "GetAllTowns",
    });
  };

  useEffect(() => {
    if (getTownsApi.data && getTownsApi.data.length) {
      setTowns(
        getTownsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log("getVehiclesActionsApi.data", getTownsApi.data);
  }, [getTownsApi.data]);
  useEffect(() => {
    getTransferPoints();
    getVehicles();
    getTowns();
  }, []);

  useEffect(() => {
    if (
      getTransferPointsActionsApi.data &&
      getTransferPointsActionsApi.data.length
    ) {
      setTransferPoints(
        getTransferPointsActionsApi.data.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }

    console.log("getRoutesActionsApi.data", getTransferPointsActionsApi.data);
  }, [getTransferPointsActionsApi.data]);
  useEffect(() => {
    if (getVehiclesActionsApi.data && getVehiclesActionsApi.data.length) {
      setVehicles(
        getVehiclesActionsApi.data.map((i) => ({
          label: i.registration,
          value: i.id,
        }))
      );
    }

    console.log("getVehiclesActionsApi.data", getVehiclesActionsApi.data);
  }, [getVehiclesActionsApi.data]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const [vehicles, setVehicles] = useState([]);

  const handleTripAction = async (data) => {
    console.log("data at", data);
    const result = await transportActionsApi.request(data);

    console.log("res", result);
    if (result.ok) {
      setUpdated(true);
    }
  };

  const handleDepartureDateChange = (date, dateString) => {
    formik.setFieldValue("departure_date", dateString);
  };

  const handleReportingTimeChange = (timeArray, time) => {
    formik.setFieldValue("reporting_time", time);
  };
  const handleDepartureTimeChange = (timeArray, time) => {
    console.log("Dep", time);
    formik.setFieldValue("departure_time", time);
  };
  const formik = useFormik({
    initialValues: {
      origin_town: journey
        ? {
            label: journey.origin_town_title,
            value: journey.origin_town,
          }
        : "",
      destination_town: journey
        ? {
            label: journey.destination_town_title,
            value: journey.destination_town,
          }
        : "",
      vehicle: journey
        ? { label: journey.vehicle_registration, value: journey.vehicle }
        : "",
      journey_fare: journey ? journey.journey_fare : "0:00",
      official_pick_up_point: journey ? journey.official_pick_up_point : "0:00",
      reporting_time: journey ? journey.reporting_time : "00:00",
      departure_time: journey ? journey.departure_time : "00:00",
      departure_date: journey ? journey.departure_date : dayjs(),
    },

    validationSchema: Yup.object({
      origin_town: Yup.object().required("Origin town is required"),
      destination_town: Yup.object().required("Destination town is required"),
      departure_date: Yup.string().required("Departure date is required"),
      departure_time: Yup.string().required("Departure time is required"),
      journey_fare: Yup.number()
        .min(1, "Cannot be 0 or less")
        .required("Fare is required"),
      is_active: Yup.bool().label("Status"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);

      if (journey) {
        handleTripAction({
          action: "UpdateJourney",
          journey_details: {
            journey_id: journey.id,
            origin_town: values.origin_town.value,
            destination_town: values.destination_town.value,
            driver: values.driver ? values.driver.value : "",
            vehicle: values.vehicle ? values.vehicle.value : "",
            departure_date: values.departure_date,
            departure_time: values.departure_time,
            reporting_time: values.reporting_time,
            journey_fare: values.journey_fare,
            is_active: values.is_active,
            official_pick_up_point: values.official_pick_up_point,
          },
        });
      } else {
        handleTripAction({
          action: "CreateJourney",
          journey_details: {
            origin_town: values.origin_town.value,
            destination_town: values.destination_town.value,
            driver: values.driver ? values.driver.value : "",
            vehicle: values.vehicle ? values.vehicle.value : "",
            departure_date: values.departure_date,
            departure_time: values.departure_time,
            reporting_time: values.reporting_time,
            journey_fare: values.journey_fare,
            is_active: values.is_active,
            official_pick_up_point: values.official_pick_up_point,
          },
        });
      }
      setisModalOpen(false);

      resetForm();
    },
  });

  const [switchStatus, setswitchStatus] = useState(
    journey && journey.is_active === "true" ? true : false
  );
  const [switchLabel, setswitchLabel] = useState("Activate");
  const handleSwitchChange = (checked) => {
    console.log("Swict", checked);
    formik.setFieldValue("is_active", checked ? "true" : "false");
    setswitchLabel(checked ? "Deactivate" : "Activate");

    // console.log('eee', e.target.checked)
  };

  const getSaccoDrivers = async () => {
    await transportActionsApi.request({
      action: "GetSaccoDrivers",
    });
  };

  useEffect(() => {
    getSaccoDrivers();
  }, []);

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.length) {
      setsaccoDrivers(transportActionsApi.data);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 1
    ) {
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_message &&
      transportActionsApi.data.response_code === 0
    ) {
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  return (
    <div className="w-full">
      <Modal
        width={720}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.origin_town}
            error={formik.errors.origin_town}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="origin_town"
              id="origin_town"
              label="Select origin town"
              size="large"
              onChange={(value) => formik.setFieldValue("origin_town", value)}
              value={formik.values.origin_town}
              placeholder="Select origin town"
              options={towns}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.destination_town}
            error={formik.errors.destination_town}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="destination_town"
              id="destination_town"
              label="Select destination town"
              size="large"
              onChange={(value) =>
                formik.setFieldValue("destination_town", value)
              }
              value={formik.values.destination_town}
              placeholder="Select destination town"
              options={towns}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.vehicle}
            error={formik.errors.vehicle}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="vehicle"
              id="vehicle"
              label="Select vehicle"
              size="large"
              onChange={(value) => formik.setFieldValue("vehicle", value)}
              value={formik.values.vehicle}
              placeholder="Select vehicle"
              options={vehicles}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.driver}
            error={formik.errors.driver}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="driver"
              id="driver"
              label="Select driver"
              size="large"
              onChange={(value) => formik.setFieldValue("driver", value)}
              value={formik.values.driver}
              placeholder="Select driver"
              options={saccoDrivers}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.departure_date}
            error={formik.errors.departure_date}
          >
            <CustomDatePicker
              id="departure_date"
              name="departure_date"
              size="large"
              placeholder="Select departure date"
              defaultValue={dayjs(formik.values.departure_date, "YYYY-MM-DD")}
              onChange={handleDepartureDateChange}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.reporting_time}
            error={formik.errors.reporting_time}
          >
            <CustomTimePicker
              id="reporting_time"
              name="reporting_time"
              size="large"
              defaultValue={dayjs(formik.values.reporting_time, "HH:mm")}
              placeholder="Select reporting time"
              onChange={handleReportingTimeChange}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.departure_time}
            error={formik.errors.departure_time}
          >
            <CustomTimePicker
              id="departure_time"
              name="departure_time"
              size="large"
              defaultValue={dayjs(formik.values.departure_time, "HH:mm")}
              placeholder="Select departure time"
              onChange={handleDepartureTimeChange}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.official_pick_up_point}
            error={formik.errors.official_pick_up_point}
          >
            <CustomInput
              required={true}
              id="official_pick_up_point"
              name="official_pick_up_point"
              onChange={formik.handleChange}
              placeholder="Depart from place name"
              size="large"
              type="text"
              value={formik.values.official_pick_up_point}
              label="Depart from place name"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.journey_fare}
            error={formik.errors.journey_fare}
          >
            <CustomInput
              required={true}
              id="journey_fare"
              name="journey_fare"
              onChange={formik.handleChange}
              placeholder="Fare"
              size="large"
              type="number"
              value={formik.values.journey_fare}
              label="Fare"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
            />
          </CustomFormItem>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}

export default IntercityFormModal;
